namespace ghidra.app.plugin.assembler.sleigh.expr.match;




using ghidra.app.plugin.processors.sleigh.expression;

/**
 * A matcher for a token or context field, constrained by its size in bits
 */
public class FieldSizeMatcher : AbstractExpressionMatcher<PatternValue> {
	protected ExpressionMatcher<object> sizeMatcher;

	public FieldSizeMatcher(ExpressionMatcher<object> sizeMatcher) : base(Set.of(typeof(ContextField), typeof(TokenField)))
    {
		this.sizeMatcher = sizeMatcher;
	}

	/* @Override */
	protected bool matchDetails(PatternValue expression,
			Map<ExpressionMatcher<object>, PatternExpression> result) {
		if (expression is ContextField) {
			ContextField cf = (ContextField) expression;
			long size = cf.getEndBit() - cf.getStartBit() + 1;
			return sizeMatcher.match(new ConstantValue(size), result);
		}
		if (expression is TokenField) {
			TokenField tf = (TokenField) expression;
			long size = tf.getBitEnd() - tf.getBitStart() + 1;
			return sizeMatcher.match(new ConstantValue(size), result);
		}
		return false;
	}
}
